// Only the zero-argument constructor slice is modeled by this fictional package.
// Read signatures are byte-faithful to the real collection declarations.
export class PrototypeSet<T> extends Set<T> {
  constructor();
  override [Symbol.iterator](): SetIterator<T>;
  override get size(): number;
  override has(value: T): boolean;
  override keys(): SetIterator<T>;
  override values(): SetIterator<T>;
  override entries(): SetIterator<[T, T]>;
}
export class PrototypeMap<K, V> extends Map<K, V> {
  constructor();
  override [Symbol.iterator](): MapIterator<[K, V]>;
  override get size(): number;
  override keys(): MapIterator<K>;
  override values(): MapIterator<V>;
  override entries(): MapIterator<[K, V]>;
  override has(key: K): boolean;
  override get(key: K): V | undefined;
}
